alter table public.ledger_transactions drop constraint ledger_transactions_type_check;
alter table public.ledger_transactions add constraint ledger_transactions_type_check check(type in('expense','income','sales','transfer','opening','balance_adjustment','investment','owner_settlement','card_settlement','card_settlement_deposit','payable_payment','expense_recognition','payroll_payment','prepaid_expense_payment'));
insert into public.ledger_categories(name,kind,cost_behavior)values('임대료','expense','fixed')on conflict(kind,name)do update set cost_behavior='fixed';

create table public.ledger_recurring_expense_plans(
 id bigint generated by default as identity primary key,name text not null check(length(btrim(name))>0),category_id bigint not null references public.ledger_categories(id)on delete restrict,
 amount numeric(16,3)not null check(amount>0),frequency text not null check(frequency in('monthly')),recognition_day smallint not null check(recognition_day between 1 and 31),
 effective_from date not null check(effective_from=date_trunc('month',effective_from)::date),effective_to date null check(effective_to is null or(effective_to>=effective_from and effective_to=(date_trunc('month',effective_to)+interval '1 month'-interval '1 day')::date)),
 party_id bigint null references public.ledger_parties(id)on delete restrict,is_active boolean not null default true,source_key_prefix text not null check(source_key_prefix~'^[a-z0-9_-]+$'),memo text null,created_by bigint null references public.users(id)on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(source_key_prefix,effective_from)
);
create table public.ledger_recurring_expense_payments(
 id bigint generated by default as identity primary key,recurring_plan_id bigint not null references public.ledger_recurring_expense_plans(id)on delete restrict,payment_transaction_id bigint not null unique references public.ledger_transactions(id)on delete restrict,
 covered_from date not null check(covered_from=date_trunc('month',covered_from)::date),covered_to date not null check(covered_to=(date_trunc('month',covered_to)+interval '1 month'-interval '1 day')::date and covered_to>=covered_from),paid_amount numeric(16,3)not null check(paid_amount>0),created_at timestamptz not null default now()
);
create table public.ledger_reserve_plans(
 id bigint generated by default as identity primary key,name text not null check(length(btrim(name))>0),target_amount numeric(16,3)not null check(target_amount>0),target_date date null,linked_recurring_plan_id bigint null references public.ledger_recurring_expense_plans(id)on delete restrict,is_active boolean not null default true,memo text null,created_by bigint null references public.users(id)on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table public.ledger_reserve_entries(
 id bigint generated by default as identity primary key,reserve_plan_id bigint not null references public.ledger_reserve_plans(id)on delete restrict,entry_type text not null check(entry_type in('allocate','release','consume','adjustment')),amount numeric(16,3)not null check(amount<>0 and(entry_type='adjustment'or amount>0)),occurred_at timestamptz not null,memo text null,created_by bigint not null references public.users(id)on delete restrict,created_at timestamptz not null default now()
);
create index ledger_recurring_plans_category_idx on public.ledger_recurring_expense_plans(category_id);create index ledger_recurring_plans_party_idx on public.ledger_recurring_expense_plans(party_id);create index ledger_recurring_plans_effective_idx on public.ledger_recurring_expense_plans(effective_from,effective_to,is_active);create index ledger_recurring_plans_created_by_idx on public.ledger_recurring_expense_plans(created_by);
create index ledger_recurring_payments_plan_idx on public.ledger_recurring_expense_payments(recurring_plan_id);create index ledger_recurring_payments_transaction_idx on public.ledger_recurring_expense_payments(payment_transaction_id);
create index ledger_reserve_plans_recurring_idx on public.ledger_reserve_plans(linked_recurring_plan_id);create index ledger_reserve_plans_created_by_idx on public.ledger_reserve_plans(created_by);create index ledger_reserve_entries_plan_date_idx on public.ledger_reserve_entries(reserve_plan_id,occurred_at);create index ledger_reserve_entries_created_by_idx on public.ledger_reserve_entries(created_by);
alter table public.ledger_recurring_expense_plans enable row level security;alter table public.ledger_recurring_expense_payments enable row level security;alter table public.ledger_reserve_plans enable row level security;alter table public.ledger_reserve_entries enable row level security;
revoke all on table public.ledger_recurring_expense_plans,public.ledger_recurring_expense_payments,public.ledger_reserve_plans,public.ledger_reserve_entries from public,anon,authenticated,service_role;
revoke all on sequence public.ledger_recurring_expense_plans_id_seq,public.ledger_recurring_expense_payments_id_seq,public.ledger_reserve_plans_id_seq,public.ledger_reserve_entries_id_seq from public,anon,authenticated,service_role;
grant select on table public.ledger_recurring_expense_plans,public.ledger_recurring_expense_payments,public.ledger_reserve_plans,public.ledger_reserve_entries to service_role;

insert into public.ledger_recurring_expense_plans(name,category_id,amount,frequency,recognition_day,effective_from,source_key_prefix,memo)
select '매장 임대료',id,60000000,'monthly',1,date '2026-08-01','rent','BABA initial monthly rent plan' from public.ledger_categories where kind='expense'and name='임대료' on conflict(source_key_prefix,effective_from)do nothing;
insert into public.ledger_reserve_plans(name,target_amount,target_date,linked_recurring_plan_id,memo)
select '다음 연간 임대료 준비금',720000000,null,id,'정확한 다음 납부일은 owner/master가 설정' from public.ledger_recurring_expense_plans where source_key_prefix='rent'and effective_from=date '2026-08-01'and not exists(select 1 from public.ledger_reserve_plans where name='다음 연간 임대료 준비금');

create or replace function public.ledger_create_recurring_plan_version_v1(p_name text,p_category_id bigint,p_amount numeric,p_recognition_day smallint,p_effective_from date,p_party_id bigint,p_source_key_prefix text,p_memo text,p_actor_user_id bigint)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare v_role text;v_previous public.ledger_recurring_expense_plans%rowtype;v_id bigint;begin select lower(role::text)into v_role from public.users where id=p_actor_user_id and is_active=true and app_login_enabled=true;if coalesce(v_role,'')not in('owner','master')then return jsonb_build_object('status','forbidden');end if;if nullif(btrim(p_name),'')is null or p_amount<=0 or scale(p_amount)>3 or p_recognition_day not between 1 and 31 or p_effective_from<>date_trunc('month',p_effective_from)::date or p_source_key_prefix!~'^[a-z0-9_-]+$'or not exists(select 1 from public.ledger_categories where id=p_category_id and kind='expense'and is_active=true)then return jsonb_build_object('status','invalid_input');end if;perform pg_advisory_xact_lock(hashtext('ledger_recurring_plan:'||p_source_key_prefix));select*into v_previous from public.ledger_recurring_expense_plans where source_key_prefix=p_source_key_prefix and is_active=true order by effective_from desc,id desc limit 1 for update;if v_previous.id is not null and p_effective_from<=v_previous.effective_from then return jsonb_build_object('status','invalid_effective_from');end if;if v_previous.id is not null then update public.ledger_recurring_expense_plans set effective_to=(p_effective_from-interval'1 day')::date,is_active=false,updated_at=now()where id=v_previous.id;end if;insert into public.ledger_recurring_expense_plans(name,category_id,amount,frequency,recognition_day,effective_from,party_id,source_key_prefix,memo,created_by)values(btrim(p_name),p_category_id,p_amount,'monthly',p_recognition_day,p_effective_from,p_party_id,btrim(p_source_key_prefix),nullif(btrim(p_memo),''),p_actor_user_id)returning id into v_id;insert into public.ledger_audit_logs(actor_user_id,action,entity_type,entity_id,before_snapshot,after_snapshot,reason)values(p_actor_user_id,'recurring_plan_version_created','recurring_plan',v_id,case when v_previous.id is null then null else to_jsonb(v_previous)end,(select to_jsonb(p)from public.ledger_recurring_expense_plans p where id=v_id),nullif(btrim(p_memo),''));return jsonb_build_object('status','created','recurringPlanId',v_id);end$$;

create or replace function public.ledger_sync_recurring_expenses_v1(p_month date,p_actor_user_id bigint)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare v_role text;v_plan public.ledger_recurring_expense_plans%rowtype;v_existing public.ledger_transactions%rowtype;v_key text;v_fp text;v_snapshot jsonb;v_date date;v_id bigint;v_created int:=0;v_updated int:=0;v_unchanged int:=0;v_total numeric:=0;
begin select lower(role::text)into v_role from public.users where id=p_actor_user_id and is_active=true and app_login_enabled=true;if coalesce(v_role,'')not in('owner','master')then return jsonb_build_object('status','forbidden');end if;if p_month is null or p_month<>date_trunc('month',p_month)::date then return jsonb_build_object('status','invalid_month');end if;
 for v_plan in select*from public.ledger_recurring_expense_plans where frequency='monthly'and effective_from<=p_month and(effective_to is null or effective_to>=p_month)order by id loop
  perform pg_advisory_xact_lock(hashtext('ledger_recurring:'||v_plan.source_key_prefix||':'||to_char(p_month,'YYYY-MM')));v_key:='recurring:'||v_plan.id||':'||to_char(p_month,'YYYY-MM');v_date:=least((p_month+(v_plan.recognition_day-1)*interval '1 day')::date,(p_month+interval '1 month'-interval '1 day')::date);v_snapshot:=jsonb_build_object('planId',v_plan.id,'planName',v_plan.name,'frequency',v_plan.frequency,'recognitionDay',v_plan.recognition_day,'effectiveFrom',v_plan.effective_from,'effectiveTo',v_plan.effective_to,'amount',v_plan.amount);v_fp:=md5(v_snapshot::text);select*into v_existing from public.ledger_transactions where source_type='recurring_expense'and source_key=v_key for update;
  if v_existing.id is null then insert into public.ledger_transactions(operation_id,type,occurred_at,business_date,recognition_month,amount,category_id,party_id,status,source_type,source_key,source_snapshot,source_fingerprint,source_synced_at,memo,created_by,confirmed_by)values(gen_random_uuid(),'expense_recognition',(v_date+time'03:00')at time zone'Asia/Ho_Chi_Minh',v_date,p_month,v_plan.amount,v_plan.category_id,v_plan.party_id,'confirmed','recurring_expense',v_key,v_snapshot,v_fp,now(),v_plan.name,p_actor_user_id,p_actor_user_id)returning id into v_id;insert into public.ledger_audit_logs(actor_user_id,action,entity_type,entity_id,after_snapshot,reason)values(p_actor_user_id,'recurring_expense_created','transaction',v_id,v_snapshot,'Recurring expense sync');v_created:=v_created+1;
  elsif v_existing.source_fingerprint=v_fp and v_existing.status='confirmed'then update public.ledger_transactions set source_synced_at=now(),updated_at=now()where id=v_existing.id;v_unchanged:=v_unchanged+1;
  else update public.ledger_transactions set occurred_at=(v_date+time'03:00')at time zone'Asia/Ho_Chi_Minh',business_date=v_date,amount=v_plan.amount,category_id=v_plan.category_id,party_id=v_plan.party_id,status='confirmed',source_snapshot=v_snapshot,source_fingerprint=v_fp,source_synced_at=now(),updated_at=now(),confirmed_by=p_actor_user_id where id=v_existing.id;insert into public.ledger_audit_logs(actor_user_id,action,entity_type,entity_id,before_snapshot,after_snapshot,reason)values(p_actor_user_id,'recurring_expense_drift_updated','transaction',v_existing.id,to_jsonb(v_existing),(select to_jsonb(t)from public.ledger_transactions t where id=v_existing.id),'Open-month recurring plan drift; future month closure uses correction');v_updated:=v_updated+1;end if;v_total:=v_total+v_plan.amount;
 end loop;return jsonb_build_object('status','ok','plansScanned',v_created+v_updated+v_unchanged,'createdCount',v_created,'updatedCount',v_updated,'unchangedCount',v_unchanged,'totalRecognizedExpense',v_total);end$$;

create or replace function public.ledger_create_prepaid_expense_payment_v1(p_plan_id bigint,p_paid_at timestamptz,p_amount numeric,p_fund_account_id bigint,p_covered_from date,p_covered_to date,p_memo text,p_actor_user_id bigint)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare v_role text;v_id bigint;v_date date;v_tx public.ledger_transactions%rowtype;begin select lower(role::text)into v_role from public.users where id=p_actor_user_id and is_active=true and app_login_enabled=true;if coalesce(v_role,'')not in('owner','master')then return jsonb_build_object('status','forbidden');end if;if p_amount is null or p_amount<=0 or scale(p_amount)>3 or p_paid_at is null then return jsonb_build_object('status','invalid_amount');end if;if not exists(select 1 from public.ledger_recurring_expense_plans where id=p_plan_id)or not exists(select 1 from public.ledger_fund_accounts where id=p_fund_account_id and is_active=true)then return jsonb_build_object('status','invalid_reference');end if;if p_covered_from<>date_trunc('month',p_covered_from)::date or p_covered_to<>(date_trunc('month',p_covered_to)+interval'1 month'-interval'1 day')::date or p_covered_to<p_covered_from then return jsonb_build_object('status','invalid_coverage');end if;v_date:=((p_paid_at at time zone'Asia/Ho_Chi_Minh')-interval'3 hours')::date;
 insert into public.ledger_transactions(operation_id,type,occurred_at,business_date,amount,status,source_type,source_snapshot,source_fingerprint,source_synced_at,memo,created_by,confirmed_by)values(gen_random_uuid(),'prepaid_expense_payment',p_paid_at,v_date,p_amount,'confirmed','recurring_expense_payment',jsonb_build_object('planId',p_plan_id,'coveredFrom',p_covered_from,'coveredTo',p_covered_to,'paidAmount',p_amount),md5(gen_random_uuid()::text),now(),nullif(btrim(p_memo),''),p_actor_user_id,p_actor_user_id)returning*into v_tx;v_id:=v_tx.id;insert into public.ledger_movements(transaction_id,fund_account_id,amount)values(v_id,p_fund_account_id,-p_amount);insert into public.ledger_recurring_expense_payments(recurring_plan_id,payment_transaction_id,covered_from,covered_to,paid_amount)values(p_plan_id,v_id,p_covered_from,p_covered_to,p_amount);insert into public.ledger_audit_logs(actor_user_id,action,entity_type,entity_id,after_snapshot,reason)values(p_actor_user_id,'prepaid_expense_payment_created','transaction',v_id,to_jsonb(v_tx),nullif(btrim(p_memo),''));return jsonb_build_object('status','created','transactionId',v_id);end$$;

create or replace function public.ledger_create_reserve_plan_v1(p_name text,p_target_amount numeric,p_target_date date,p_linked_plan_id bigint,p_memo text,p_actor_user_id bigint)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare v_role text;v_id bigint;begin select lower(role::text)into v_role from public.users where id=p_actor_user_id and is_active=true and app_login_enabled=true;if coalesce(v_role,'')not in('owner','master')then return jsonb_build_object('status','forbidden');end if;if nullif(btrim(p_name),'')is null or p_target_amount<=0 or scale(p_target_amount)>3 then return jsonb_build_object('status','invalid_input');end if;insert into public.ledger_reserve_plans(name,target_amount,target_date,linked_recurring_plan_id,memo,created_by)values(btrim(p_name),p_target_amount,p_target_date,p_linked_plan_id,nullif(btrim(p_memo),''),p_actor_user_id)returning id into v_id;insert into public.ledger_audit_logs(actor_user_id,action,entity_type,entity_id,after_snapshot,reason)values(p_actor_user_id,'reserve_plan_created','reserve_plan',v_id,(select to_jsonb(r)from public.ledger_reserve_plans r where id=v_id),nullif(btrim(p_memo),''));return jsonb_build_object('status','created','reservePlanId',v_id);end$$;
create or replace function public.ledger_create_reserve_entry_v1(p_reserve_plan_id bigint,p_entry_type text,p_amount numeric,p_occurred_at timestamptz,p_memo text,p_actor_user_id bigint)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare v_role text;v_id bigint;v_current numeric;v_delta numeric;begin select lower(role::text)into v_role from public.users where id=p_actor_user_id and is_active=true and app_login_enabled=true;if coalesce(v_role,'')not in('owner','master')then return jsonb_build_object('status','forbidden');end if;perform 1 from public.ledger_reserve_plans where id=p_reserve_plan_id and is_active=true for update;if not found then return jsonb_build_object('status','invalid_plan');end if;if p_entry_type not in('allocate','release','consume','adjustment')or p_amount is null or p_amount=0 or(p_entry_type<>'adjustment'and p_amount<0)or scale(p_amount)>3 or p_occurred_at is null then return jsonb_build_object('status','invalid_entry');end if;select coalesce(sum(case entry_type when'allocate'then amount when'release'then-amount when'consume'then-amount else amount end),0)into v_current from public.ledger_reserve_entries where reserve_plan_id=p_reserve_plan_id;v_delta:=case p_entry_type when'allocate'then p_amount when'release'then-p_amount when'consume'then-p_amount else p_amount end;if v_current+v_delta<0 then return jsonb_build_object('status','insufficient_reserve','currentAmount',v_current);end if;insert into public.ledger_reserve_entries(reserve_plan_id,entry_type,amount,occurred_at,memo,created_by)values(p_reserve_plan_id,p_entry_type,p_amount,p_occurred_at,nullif(btrim(p_memo),''),p_actor_user_id)returning id into v_id;insert into public.ledger_audit_logs(actor_user_id,action,entity_type,entity_id,before_snapshot,after_snapshot,reason)values(p_actor_user_id,'reserve_entry_created','reserve_entry',v_id,jsonb_build_object('reserveAmount',v_current),jsonb_build_object('reservePlanId',p_reserve_plan_id,'entryType',p_entry_type,'amount',p_amount,'reserveAmount',v_current+v_delta),nullif(btrim(p_memo),''));return jsonb_build_object('status','created','reserveEntryId',v_id,'currentAmount',v_current+v_delta);end$$;

create or replace function public.ledger_update_reserve_plan_v1(p_reserve_plan_id bigint,p_target_amount numeric,p_target_date date,p_memo text,p_actor_user_id bigint)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare v_role text;v_before public.ledger_reserve_plans%rowtype;begin select lower(role::text)into v_role from public.users where id=p_actor_user_id and is_active=true and app_login_enabled=true;if coalesce(v_role,'')not in('owner','master')then return jsonb_build_object('status','forbidden');end if;select*into v_before from public.ledger_reserve_plans where id=p_reserve_plan_id and is_active=true for update;if v_before.id is null then return jsonb_build_object('status','not_found');end if;if p_target_amount<=0 or scale(p_target_amount)>3 then return jsonb_build_object('status','invalid_input');end if;update public.ledger_reserve_plans set target_amount=p_target_amount,target_date=p_target_date,memo=nullif(btrim(p_memo),''),updated_at=now()where id=p_reserve_plan_id;insert into public.ledger_audit_logs(actor_user_id,action,entity_type,entity_id,before_snapshot,after_snapshot,reason)values(p_actor_user_id,'reserve_plan_updated','reserve_plan',p_reserve_plan_id,to_jsonb(v_before),(select to_jsonb(r)from public.ledger_reserve_plans r where id=p_reserve_plan_id),nullif(btrim(p_memo),''));return jsonb_build_object('status','updated','reservePlanId',p_reserve_plan_id);end$$;

revoke all on function public.ledger_create_recurring_plan_version_v1(text,bigint,numeric,smallint,date,bigint,text,text,bigint),public.ledger_sync_recurring_expenses_v1(date,bigint),public.ledger_create_prepaid_expense_payment_v1(bigint,timestamptz,numeric,bigint,date,date,text,bigint),public.ledger_create_reserve_plan_v1(text,numeric,date,bigint,text,bigint),public.ledger_create_reserve_entry_v1(bigint,text,numeric,timestamptz,text,bigint),public.ledger_update_reserve_plan_v1(bigint,numeric,date,text,bigint)from public,anon,authenticated;
grant execute on function public.ledger_create_recurring_plan_version_v1(text,bigint,numeric,smallint,date,bigint,text,text,bigint),public.ledger_sync_recurring_expenses_v1(date,bigint),public.ledger_create_prepaid_expense_payment_v1(bigint,timestamptz,numeric,bigint,date,date,text,bigint),public.ledger_create_reserve_plan_v1(text,numeric,date,bigint,text,bigint),public.ledger_create_reserve_entry_v1(bigint,text,numeric,timestamptz,text,bigint),public.ledger_update_reserve_plan_v1(bigint,numeric,date,text,bigint)to service_role;
comment on table public.ledger_reserve_entries is 'Virtual earmarks only: reserve entries create neither ledger movements nor profit transactions.';
